-- Test fixture setup (in-memory SQLite)
CREATE TABLE users (
    id INTEGER PRIMARY KEY,
    username TEXT NOT NULL,
    role TEXT NOT NULL
);

INSERT INTO users (username, role) VALUES
    ('alice', 'admin'),
    ('bob', 'user'),
    ('carol', 'user');

-- Representative SQL injection inputs (as data, not executed)
-- 1. Tautology: always-true condition to bypass authentication
SET @tautology_input = "' OR 1=1 --";

-- 2. UNION: extract data from other tables
SET @union_input = "' UNION SELECT id, username, role FROM users --";

-- 3. Comment truncation: cut off the rest of the query
SET @comment_input = "'; DROP TABLE users; --";

-- Parameterized query (using prepared statement)
PREPARE safe_query FROM 
    'SELECT * FROM users WHERE username = ? AND role = ?';

-- Execute with each input as a parameter (data, not code)
EXECUTE safe_query USING @tautology_input, 'user';
-- Expected: 0 rows (no user named "' OR 1=1 --")

EXECUTE safe_query USING @union_input, 'user';
-- Expected: 0 rows (no user named "' UNION SELECT ...")

EXECUTE safe_query USING @comment_input, 'user';
-- Expected: 0 rows (no user named "'; DROP TABLE users; --")

-- Assertions (in test framework)
-- Assert that each query returned exactly 0 rows
-- And that the users table still exists (no DROP executed)
SELECT COUNT(*) = 0 FROM 
    (SELECT * FROM users WHERE username = @tautology_input AND role = 'user');
SELECT COUNT(*) = 0 FROM 
    (SELECT * FROM users WHERE username = @union_input AND role = 'user');
SELECT COUNT(*) = 0 FROM 
    (SELECT * FROM users WHERE username = @comment_input AND role = 'user');

-- Verify table integrity (comment truncation didn't drop anything)
SELECT COUNT(*) = 3 FROM users;
